/// <summary>
/// class <c>METTelemetrySOConfirmationInfoEvent</c> is used to log event whenever the order processing status is updated as optimization completed.
/// </summary>
internal final class METTelemetrySOConfirmationInfoEvent extends ISMTelemetryBase
{
}

Method.Source:
/// <summary>
/// Initialize the class <c>METTelemetrySOConfirmationInfoEvent</c>
/// </summary>
/// <returns> Instance of class <c>METTelemetrySOConfirmationInfoEvent</c> </returns>
public static METTelemetrySOConfirmationInfoEvent construct()
{
    return new METTelemetrySOConfirmationInfoEvent();
}

/// <summary>
/// if the log level is set to information it will log the request and response data as wekk as there is an error
/// </summary>
/// <returns> a boolean value </returns>
protected boolean shouldLogEvent()
{
    return true;
}

/// <summary>
/// Add runtime telemetry property to application insights.
/// </summary>
/// <param name = "_salesTable"> instanse of table <c>salesTable</c> </param>
/// <param name = "_metSalesTable"> instanse of table <c>metSalesTable</c> </param>
public void addRunTimePropertyToAppinsights(SalesTable _salesTable, CustConfirmJour _confirmJournal)
{
    METSalesTable metSalestable = METSalesTable::findBySalesTable(_salesTable.RecId);

    this.addRuntimeProperty(METTelemetryProperties::salesOrderNumber, _salesTable.SalesId);
    this.addRuntimeProperty(METTelemetryProperties::warehouseId,_salesTable.InventLocationId);
    this.addRuntimeProperty(METTelemetryProperties::orderReferenceNumber, _salesTable.CustomerRef);
    this.addRuntimeProperty(METTelemetryProperties::industryKey, metSalestable.IndustryKey);
    this.addRuntimeProperty(METTelemetryProperties::metcashSalesOrderType, _salesTable.METSalesOrderType);
    this.addRuntimeProperty(METTelemetryProperties::customerNumber, _salesTable.CustAccount);
    this.addRuntimeProperty(METTelemetryProperties::transmissionNumber, metSalestable.TransmissionNumber);
    this.addRuntimeProperty(METTelemetryProperties::confirmDocNum, _confirmJournal.ConfirmDocNum);
}
